//! The Solid translation: each component's template as a Solid component,
//! for the POS. `cargo xtask ui` writes these files into
//! crates/ui/solid; nothing there is edited by hand.

use std::collections::BTreeMap;
use std::fmt::Write;

use crate::ir::{Attr, Cond, Element, Node, Part, Path};
use crate::{ComponentInfo, Ty, Value};

/// Every generated file, by its name under crates/ui/solid.
pub fn files(components: &[&'static ComponentInfo]) -> BTreeMap<String, String> {
    let mut files = BTreeMap::new();
    let mut types = Types::default();
    let mut index = String::from(HEADER);
    let mut islands = String::from(HEADER);
    let interactive: Vec<_> = components
        .iter()
        .filter(|i| i.behaviour.is_some())
        .collect();
    for info in &interactive {
        let _ = writeln!(islands, "import {{ attach{0} }} from './{0}';", info.name);
    }
    islands.push_str("\n/** Each interactive component's attach, by the name its island gives. */\nexport const islands: Record<string, (root: Element, props: never) => () => void> = {\n");
    for info in &interactive {
        let _ = writeln!(islands, "  {0}: attach{0},", info.name);
    }
    islands.push_str("};\n");
    for info in components {
        let source = component(info, &mut types);
        files.insert(format!("{}.tsx", info.name), source);
        let _ = writeln!(index, "export * from './{}';", info.name);
    }
    index.push_str("export * from './types';\n");
    files.insert("index.ts".into(), index);
    files.insert("islands.ts".into(), islands);
    files.insert("types.ts".into(), types.source());
    files.insert("runtime.ts".into(), RUNTIME.into());
    files
}

const HEADER: &str = "// Generated by `cargo xtask ui` from crates/ui. Do not edit: change the\n// component there and run it again.\n\n";

const RUNTIME: &str = "// Generated by `cargo xtask ui` from crates/ui. Do not edit: change the
// component there and run it again.
import { onCleanup } from 'solid-js';

/** The tokens of a `join[...]` attribute that are present, space-separated;
 *  `undefined`, so the attribute is left out, when none are. */
export function tokens<T extends string>(...items: (T | false | undefined)[]): T | undefined {
  const present = items.filter((item): item is T => typeof item === 'string');
  // One token is one of the literals given (a `role`); several, a list.
  return present.length > 0 ? (present.join(' ') as T) : undefined;
}

/** The island an element is in: the nearest `data-island` around it. */
const islandOf = (node: Node | null): Element | null | undefined =>
  (node instanceof Element ? node : node?.parentElement)?.closest('[data-island]');

/** The server-rendered element an island's behaviour attaches to
 *  (`data-mk`), not one of a nested island's. The root is the island. */
export function mark(root: Element, n: number): HTMLElement | null {
  if (root instanceof HTMLElement && root.dataset.mk === String(n)) return root;
  const found = Array.from(root.querySelectorAll<HTMLElement>(`[data-mk=\"${n}\"]`));
  return found.find(element => islandOf(element) === root) ?? null;
}

/** Every server-rendered element with one mark, in order: the elements of
 *  a loop over a prop's list, one per item. */
export function marks(root: Element, n: number): HTMLElement[] {
  return Array.from(root.querySelectorAll<HTMLElement>(`[data-mk=\"${n}\"]`)).filter(element => islandOf(element) === root);
}

/** The comment the server left where enhanced markup goes (`<!--mk:N-->`). */
export function marker(root: Element, n: number): Comment | null {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_COMMENT);
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    if (node.nodeValue === `mk:${n}` && islandOf(node) === root) return node as Comment;
  }
  return null;
}

/** Takes away what the server rendered between a marker and its end
 *  (`<!--/mk:N-->`): an `@if enhanced`'s fallback. */
export function clear(marker: Comment, n: number): void {
  let node = marker.nextSibling;
  while (node) {
    const next = node.nextSibling;
    const end = node.nodeType === Node.COMMENT_NODE && node.nodeValue === `/mk:${n}`;
    node.remove();
    if (end) return;
    node = next;
  }
}

/** Sets an attribute as JSX would: `true` present and empty, `false` or
 *  `undefined` absent. */
export function setAttr(element: Element, name: string, value: unknown): void {
  if (value === undefined || value === null || value === false) element.removeAttribute(name);
  else element.setAttribute(name, value === true ? '' : String(value));
}

/** Listens until the island's behaviour is disposed. */
export function on(element: Element, event: string, handler: (event: Event) => void): void {
  element.addEventListener(event, handler);
  onCleanup(() => element.removeEventListener(event, handler));
}
";

/// The enums and records the components use, written once into types.ts.
#[derive(Default)]
struct Types {
    /// Whether a record holds markup, so types.ts needs `JSX`.
    markup: bool,
    enums: BTreeMap<&'static str, String>,
    records: BTreeMap<&'static str, String>,
}

impl Types {
    /// The TypeScript type for `ty`, noting any enum or record it names.
    fn ts(&mut self, ty: &Ty, used: &mut Vec<&'static str>) -> String {
        match ty {
            Ty::Text => "string".into(),
            Ty::Bool => "boolean".into(),
            Ty::Number => "number".into(),
            Ty::Slot => "JSX.Element".into(),
            Ty::Attrs => unreachable!("a spread isn't a prop of its own"),
            Ty::Option(inner) => self.ts(inner, used),
            Ty::List(inner) => format!("readonly {}[]", self.ts(inner, used)),
            Ty::Enum(info) => {
                if !self.enums.contains_key(info.name) {
                    let mut s = doc(info.doc, "");
                    let values: Vec<String> = info
                        .variants
                        .iter()
                        .map(|v| format!("{:?}", v.value))
                        .collect();
                    let _ = writeln!(s, "export type {} = {};", info.name, values.join(" | "));
                    self.enums.insert(info.name, s);
                }
                used.push(info.name);
                info.name.into()
            }
            Ty::Record(info) => {
                let info = info();
                if !self.records.contains_key(info.name) {
                    let mut fields = String::new();
                    let mut nested = Vec::new();
                    for field in &info.fields {
                        self.markup |= matches!(field.ty, Ty::Slot);
                        fields.push_str(&doc(field.doc, "  "));
                        let optional = if matches!(field.ty, Ty::Option(_)) {
                            "?"
                        } else {
                            ""
                        };
                        let ty = self.ts(&field.ty, &mut nested);
                        let _ = writeln!(fields, "  readonly {}{optional}: {ty};", field.name);
                    }
                    let mut s = doc(info.doc, "");
                    let _ = write!(s, "export interface {} {{\n{fields}}}\n", info.name);
                    self.records.insert(info.name, s);
                }
                used.push(info.name);
                info.name.into()
            }
        }
    }

    fn source(&self) -> String {
        let mut s = String::from(HEADER);
        if self.markup {
            s.push_str("import type { JSX } from '@solidjs/web';\n");
        }
        for body in self.enums.values().chain(self.records.values()) {
            s.push('\n');
            s.push_str(body);
        }
        s
    }
}

fn doc(text: &str, indent: &str) -> String {
    if text.is_empty() {
        return String::new();
    }
    let mut s = format!("{indent}/**\n");
    for line in text.lines() {
        if line.is_empty() {
            let _ = writeln!(s, "{indent} *");
        } else {
            let _ = writeln!(s, "{indent} * {line}");
        }
    }
    let _ = writeln!(s, "{indent} */");
    s
}

/// A TypeScript literal for a default.
fn literal(value: &Value) -> String {
    match value {
        Value::Text(s) => format!("{s:?}"),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::Enum(s) => format!("{s:?}"),
        other => panic!("{other:?} can't be a default"),
    }
}

fn component(info: &'static ComponentInfo, types: &mut Types) -> String {
    let mut used = Vec::new();
    let mut fields = String::new();
    let mut rest = None;
    for prop in &info.props {
        if matches!(prop.ty, Ty::Attrs) {
            rest = Some(prop.name);
            continue;
        }
        let mut text = prop.doc.to_string();
        if let Some(default) = &prop.default {
            if !text.is_empty() {
                text.push('\n');
            }
            let _ = write!(text, "@default {}", literal(default));
        }
        fields.push_str(&doc(&text, "  "));
        let optional = if prop.required { "" } else { "?" };
        let ty = types.ts(&prop.ty, &mut used);
        let _ = writeln!(fields, "  {}{optional}: {ty};", prop.name);
    }
    let behaviour = info.behaviour.as_ref();
    let mut behaviour_fields = String::new();
    if let Some(b) = behaviour {
        fields.push_str("  /**\n   * `false` renders the server's markup, without the behaviour's (tests).\n   * @default true\n   */\n  enhanced?: boolean;\n");
        for value in &b.values {
            behaviour_fields.push_str(&doc(value.doc, "  "));
            let mut ty = types.ts(&value.ty, &mut used);
            if matches!(value.ty, Ty::Option(_)) {
                ty.push_str(" | undefined");
            }
            let _ = writeln!(
                behaviour_fields,
                "  readonly {}: Accessor<{ty}>;",
                value.name
            );
        }
        for (name, arg) in &b.handlers {
            let param = match arg {
                Some(ty) => format!("value: {}, event: Event", types.ts(ty, &mut used)),
                None => "event: Event".into(),
            };
            let _ = writeln!(behaviour_fields, "  readonly {name}: ({param}) => void;");
        }
        for name in &b.refs {
            let _ = writeln!(
                behaviour_fields,
                "  readonly {name}: (element: HTMLElement) => void;"
            );
        }
    }
    used.sort_unstable();
    used.dedup();

    let mut out = Out {
        info,
        source: String::new(),
        scope: Vec::new(),
        uses_for: false,
        uses_tokens: false,
        uses_runtime: Vec::new(),
        uses_render_effect: false,
        attaching: false,
    };
    let body = out.expression(&info.template, 2);
    let attach = behaviour.map(|_| out.attach(&info.template));

    let mut s = String::from(HEADER);
    let mut solid = Vec::new();
    if behaviour.is_some() {
        solid.extend(["createRoot", "onCleanup"]);
    }
    let owns_refs = body.contains("runWithOwner(owner")
        || attach.as_ref().is_some_and(|a| a.contains("runWithOwner(owner"));
    if owns_refs {
        solid.extend(["getOwner", "runWithOwner"]);
    }
    if out.uses_render_effect {
        solid.push("createRenderEffect");
    }
    if out.uses_for {
        solid.push("For");
    }
    if rest.is_some() {
        solid.push("omit");
    }
    if !solid.is_empty() {
        let _ = writeln!(s, "import {{ {} }} from 'solid-js';", solid.join(", "));
    }
    if behaviour.is_some() {
        s.push_str("import type { Accessor } from 'solid-js';\nimport { insert, registerDelegatedRoot, unregisterDelegatedRoot } from '@solidjs/web';\n");
    }
    s.push_str("import type { JSX } from '@solidjs/web';\n");
    let mut runtime = out.uses_runtime.clone();
    if out.uses_tokens {
        runtime.push("tokens");
    }
    runtime.sort_unstable();
    runtime.dedup();
    if !runtime.is_empty() {
        let _ = writeln!(s, "import {{ {} }} from './runtime';", runtime.join(", "));
    }
    if let Some(b) = behaviour {
        let _ = writeln!(
            s,
            "import {{ setup }} from '../web/components/{}';",
            b.file.trim_end_matches(".ts")
        );
    }
    if !used.is_empty() {
        let _ = writeln!(s, "import type {{ {} }} from './types';", used.join(", "));
    }
    s.push('\n');
    s.push_str(&doc(info.doc, ""));
    let props_name = format!("{}Props", info.name);
    match rest {
        Some(_) => {
            let mut targets = Vec::new();
            spread_targets(&info.template, &mut targets);
            assert!(!targets.is_empty(), "a rest prop is spread somewhere");
            let mut owned: Vec<String> = info
                .props
                .iter()
                .filter(|p| !matches!(p.ty, Ty::Attrs))
                .map(|p| format!("{:?}", p.name))
                .collect();
            for attr in targets.iter().flat_map(|t| &t.attrs) {
                owned.push(format!("{:?}", attr.name()));
            }
            owned.extend(["\"class\"", "\"classList\"", "\"style\""].map(String::from));
            // Spread on different elements (a `p` or a `div`): what they
            // share, less `ref`, which can't know which it gets.
            let base = if targets.iter().all(|t| t.tag == targets[0].tag) {
                format!("JSX.IntrinsicElements[{:?}]", targets[0].tag)
            } else {
                owned.push("\"ref\"".into());
                "JSX.HTMLAttributes<HTMLElement>".to_string()
            };
            owned.sort();
            owned.dedup();
            let _ = writeln!(
                s,
                "export interface {props_name} extends Omit<{base}, {}> {{\n{fields}}}\n",
                owned.join(" | ")
            );
        }
        None => {
            let _ = writeln!(s, "export interface {props_name} {{\n{fields}}}\n");
        }
    }
    s.push_str(&doc(info.doc, ""));
    let _ = writeln!(
        s,
        "export function {}(props: {props_name}): JSX.Element {{",
        info.name
    );
    if let Some(rest) = rest {
        let mut names: Vec<String> = info
            .props
            .iter()
            .filter(|p| !matches!(p.ty, Ty::Attrs))
            .map(|p| format!("{:?}", p.name))
            .collect();
        if behaviour.is_some() {
            names.push("\"enhanced\"".into());
        }
        let _ = writeln!(s, "  const {rest} = omit(props, {});", names.join(", "));
    }
    if behaviour.is_some() {
        s.push_str("  const enhanced = props.enhanced ?? true;\n  const b = setup(props);\n");
        if owns_refs {
            s.push_str("  const owner = getOwner();\n");
        }
    }
    let _ = write!(s, "  return (\n{body}  );\n}}\n");
    if let Some(attach) = attach {
        let owner = if attach.contains("runWithOwner(owner") {
            "    const owner = getOwner();\n"
        } else {
            ""
        };
        let _ = write!(
            s,
            "\n/** What the behaviour gives the template (`behaviour` in crates/ui). */\nexport interface {0}Behaviour {{\n{behaviour_fields}}}\n\n\
             /** Attaches the behaviour to the server's markup in its island, adding\n * only what `@if enhanced` renders. Returns what disposes it. */\n\
             export function attach{0}(root: Element, props: {0}Props): () => void {{\n  return createRoot((dispose) => {{\n    const enhanced = true;\n    // Solid's delegated events (onClick and the like) listen on a\n    // registered root: the island.\n    registerDelegatedRoot(root);\n    onCleanup(() => unregisterDelegatedRoot(root));\n    const b = setup(props);\n{owner}{attach}    return dispose;\n  }});\n}}\n",
            info.name
        );
    }
    s
}

/// The elements a rest prop is spread on: one, or one per branch of an `@if`.
fn spread_targets(nodes: &'static [Node], out: &mut Vec<&'static Element>) {
    for node in nodes {
        match node {
            Node::Element(e) => {
                if e.spread.is_some() {
                    out.push(e);
                }
                if let Some(children) = e.children.as_deref() {
                    spread_targets(children, out);
                }
            }
            Node::If {
                then, otherwise, ..
            }
            | Node::IfLet {
                then, otherwise, ..
            } => {
                spread_targets(then, out);
                spread_targets(otherwise, out);
            }
            Node::For { body, .. } | Node::Enhanced { body, .. } => spread_targets(body, out),
            Node::Text(_) | Node::Value(_) => {}
        }
    }
}

struct Out {
    info: &'static ComponentInfo,
    source: String,
    /// Names bound by `@for` and `@if let`: their expression and type.
    scope: Vec<(&'static str, String, Ty)>,
    uses_for: bool,
    uses_tokens: bool,
    /// Helpers from runtime.ts the attach function calls.
    uses_runtime: Vec<&'static str>,
    /// The attach function keeps an attribute up to date.
    uses_render_effect: bool,
    /// Writing the markup `attach` inserts: it can't hold a slot, which the
    /// island's props leave out.
    attaching: bool,
}

/// Whether any element in `nodes` is one the behaviour attaches to.
fn has_marks(nodes: &[Node]) -> bool {
    nodes.iter().any(|node| match node {
        Node::Element(e) => e.mark.is_some() || e.children.as_deref().is_some_and(has_marks),
        Node::If {
            then, otherwise, ..
        } => has_marks(then) || has_marks(otherwise),
        Node::Enhanced { .. } => true,
        Node::For { body, .. } => has_marks(body),
        Node::IfLet { .. } | Node::Text(_) | Node::Value(_) => false,
    })
}

/// `on:keydown` as Solid's JSX names it.
fn event_prop(event: &str) -> String {
    let camel = match event {
        "click" => "Click",
        "input" => "Input",
        "change" => "Change",
        "focus" => "Focus",
        "blur" => "Blur",
        "focusin" => "FocusIn",
        "focusout" => "FocusOut",
        "keydown" => "KeyDown",
        "keyup" => "KeyUp",
        "mousedown" => "MouseDown",
        "pointerdown" => "PointerDown",
        other => panic!("add `{other}` to solid::event_prop"),
    };
    format!("on{camel}")
}

impl Out {
    /// The TypeScript expression for a path, and its type.
    fn path(&self, path: Path) -> (String, Ty) {
        let (first, rest) = path.split_first().expect("a path");
        let mut rest = rest;
        let (mut expr, mut ty) = if let Some((_, expr, ty)) =
            self.scope.iter().rev().find(|(name, _, _)| name == first)
        {
            (expr.clone(), *ty)
        } else if *first == "b" {
            let (name, more) = rest.split_first().expect("b.name");
            rest = more;
            let value = self
                .info
                .behaviour
                .as_ref()
                .and_then(|b| b.values.iter().find(|v| v.name == *name))
                .unwrap_or_else(|| panic!("no behaviour value `{name}`"));
            (format!("b.{name}()"), value.ty)
        } else {
            let prop = self
                .info
                .prop(first)
                .unwrap_or_else(|| panic!("no prop `{first}`"));
            let expr = match &prop.default {
                Some(default) => format!("(props.{first} ?? {})", literal(default)),
                None => format!("props.{first}"),
            };
            (expr, prop.ty)
        };
        for field in rest {
            let Ty::Record(record) = ty else {
                panic!("`{field}` read from something that isn't a record")
            };
            let field_info = record()
                .fields
                .iter()
                .find(|f| f.name == *field)
                .unwrap_or_else(|| panic!("no field `{field}`"));
            expr = format!("{expr}.{field}");
            ty = field_info.ty;
        }
        (expr, ty)
    }

    fn cond(&self, cond: &Cond) -> String {
        match cond {
            Cond::Truthy(path) => {
                let (expr, ty) = self.path(path);
                match ty {
                    Ty::Bool => expr,
                    Ty::Option(_) => format!("{expr} != null"),
                    Ty::List(_) => format!("{expr}.length > 0"),
                    _ => format!("!!{expr}"),
                }
            }
            Cond::Not(inner) => format!("!({})", self.cond(inner)),
            Cond::Eq(path, value, equal) => {
                let (expr, _) = self.path(path);
                let op = if *equal { "===" } else { "!==" };
                format!("{expr} {op} {value:?}")
            }
            Cond::Same(a, b, equal) => {
                let op = if *equal { "===" } else { "!==" };
                format!("{} {op} {}", self.path(a).0, self.path(b).0)
            }
            Cond::Enhanced => "enhanced".into(),
        }
    }

    fn parts(&self, parts: &[Part]) -> String {
        let mut s = String::from("`");
        for part in parts {
            match part {
                Part::Lit(lit) => {
                    s.push_str(
                        &lit.replace('\\', "\\\\")
                            .replace('`', "\\`")
                            .replace("${", "\\${"),
                    );
                }
                Part::Value(path) => {
                    let _ = write!(s, "${{{}}}", self.path(path).0);
                }
            }
        }
        s.push('`');
        s
    }

    /// An attribute's name and the TypeScript expression for its value, as
    /// `setAttr` takes it; `None` for `on:` and `ref=`.
    fn attr_value(&mut self, attr: &Attr) -> Option<(&'static str, String)> {
        let value = match attr {
            Attr::Static(name, value) => (*name, format!("{value:?}")),
            Attr::Flag(name) => (*name, "true".into()),
            Attr::Value(name, path) | Attr::Optional(name, path) => (*name, self.path(path).0),
            Attr::Concat(name, parts) => (*name, self.parts(parts)),
            Attr::Bool(name, cond) => (*name, self.cond(cond)),
            Attr::When(name, parts, cond) => (
                *name,
                format!("{} ? {} : undefined", self.cond(cond), self.parts(parts)),
            ),
            Attr::Tokens(name, tokens) => (*name, self.tokens(tokens)),
            Attr::On(..) | Attr::Ref(_) => return None,
        };
        Some(value)
    }

    /// A `join[...]` attribute's value: the tokens whose conditions hold.
    fn tokens(&mut self, tokens: &[(Vec<Part>, Option<Cond>)]) -> String {
        self.uses_tokens = true;
        let items: Vec<String> = tokens
            .iter()
            .map(|(parts, cond)| {
                let value = self.parts(parts);
                match cond {
                    Some(cond) => format!("{} && {value}", self.cond(cond)),
                    None => value,
                }
            })
            .collect();
        format!("tokens({})", items.join(", "))
    }

    /// A handler as a function the event calls.
    fn handler(&self, handler: &str, arg: Option<Path>) -> String {
        match arg {
            Some(path) => format!(
                "(event: Event) => b.{handler}({}, event)",
                self.path(path).0
            ),
            None => format!("b.{handler}"),
        }
    }

    /// The body of `attach<Name>`: for each element the behaviour attaches
    /// to, its enhanced attributes (kept up to date when they read `b.*`),
    /// handlers and refs; for each `@if enhanced`, its markup inserted at
    /// the server's marker. Elements in a loop over a prop's list are found
    /// by their item's position.
    fn attach(&mut self, nodes: &[Node]) -> String {
        let mut s = String::new();
        self.attach_into(nodes, &mut s, 2, None);
        s
    }

    fn attach_into(&mut self, nodes: &[Node], s: &mut String, depth: usize, index: Option<&str>) {
        let indent = pad(depth);
        for node in nodes {
            match node {
                Node::Element(element) => {
                    if let Some(mark) = element.mark {
                        let find = match index {
                            Some(i) => {
                                self.uses_runtime.push("marks");
                                format!("marks(root, {mark})[{i}]")
                            }
                            None => {
                                self.uses_runtime.push("mark");
                                format!("mark(root, {mark})")
                            }
                        };
                        let _ = writeln!(
                            s,
                            "{indent}const n{mark} = {find};\n{indent}if (n{mark}) {{"
                        );
                        for attr in element.attrs.iter().filter(|a| a.enhanced()) {
                            match attr {
                                Attr::On(event, handler, arg) => {
                                    self.uses_runtime.push("on");
                                    let _ = writeln!(
                                        s,
                                        "{indent}  on(n{mark}, {event:?}, {});",
                                        self.handler(handler, *arg)
                                    );
                                }
                                Attr::Ref(name) => {
                                    let _ = writeln!(s, "{indent}  b.{name}(n{mark});");
                                }
                                _ => {
                                    self.uses_runtime.push("setAttr");
                                    let (name, value) =
                                        self.attr_value(attr).expect("an attribute");
                                    if attr.reads_behaviour() {
                                        self.uses_render_effect = true;
                                        let _ = writeln!(
                                            s,
                                            "{indent}  createRenderEffect(() => {value}, (value) => setAttr(n{mark}, {name:?}, value));"
                                        );
                                    } else {
                                        let _ = writeln!(
                                            s,
                                            "{indent}  setAttr(n{mark}, {name:?}, {value});"
                                        );
                                    }
                                }
                            }
                        }
                        let _ = writeln!(s, "{indent}}}");
                    }
                    if let Some(children) = &element.children {
                        self.attach_into(children, s, depth, index);
                    }
                }
                Node::Enhanced {
                    mark,
                    body,
                    fallback,
                } => {
                    self.uses_runtime.push("marker");
                    self.attaching = true;
                    let jsx = self.expression(body, depth + 2);
                    self.attaching = false;
                    let _ = writeln!(
                        s,
                        "{indent}const m{mark} = marker(root, {mark});\n{indent}if (m{mark}) {{"
                    );
                    if !fallback.is_empty() {
                        // The server's fallback goes.
                        self.uses_runtime.push("clear");
                        let _ = writeln!(s, "{indent}  clear(m{mark}, {mark});");
                    }
                    let _ = write!(
                        s,
                        "{indent}  insert(m{mark}.parentNode!, () => (\n{jsx}{indent}  ), m{mark});\n{indent}}}\n"
                    );
                }
                Node::If {
                    then, otherwise, ..
                } => {
                    self.attach_into(then, s, depth, index);
                    self.attach_into(otherwise, s, depth, index);
                }
                Node::For { bind, path, body } if index.is_none() && has_marks(body) => {
                    let (expr, ty) = self.path(path);
                    let Ty::List(item) = ty else {
                        panic!("@for runs over a list")
                    };
                    let i = format!("{bind}Index");
                    let _ = writeln!(s, "{indent}({expr}).forEach(({bind}, {i}) => {{");
                    self.scope.push((bind, (*bind).to_string(), *item));
                    self.attach_into(body, s, depth + 1, Some(&i));
                    self.scope.pop();
                    let _ = writeln!(s, "{indent}}});");
                }
                // `prepare` keeps marks out of `@if let` and nested loops.
                Node::For { .. } | Node::IfLet { .. } | Node::Text(_) | Node::Value(_) => {}
            }
        }
    }

    fn attr(&mut self, attr: &Attr) -> String {
        // An attribute that reads the behaviour's values is the behaviour's:
        // absent from the markup without it.
        if attr.reads_behaviour() {
            let (name, value) = self.attr_value(attr).expect("an attribute");
            return format!("{name}={{enhanced ? {value} : undefined}}");
        }
        match attr {
            Attr::Static(name, value) => format!("{name}={}", string_attr(value)),
            Attr::Flag(name) => (*name).to_string(),
            Attr::Value(name, path) => format!("{name}={{{}}}", self.path(path).0),
            Attr::Concat(name, parts) => format!("{name}={{{}}}", self.parts(parts)),
            Attr::Bool(name, cond) => format!("{name}={{{}}}", self.cond(cond)),
            Attr::Optional(name, path) => format!("{name}={{{}}}", self.path(path).0),
            Attr::When(name, parts, cond) => {
                format!(
                    "{name}={{{} ? {} : undefined}}",
                    self.cond(cond),
                    self.parts(parts)
                )
            }
            Attr::Tokens(name, tokens) => format!("{name}={{{}}}", self.tokens(tokens)),
            Attr::On(event, handler, arg) => {
                format!("{}={{{}}}", event_prop(event), self.handler(handler, *arg))
            }
            // Solid runs a ref outside the component's owner: run it in it,
            // so what the behaviour does there (onCleanup) is the component's.
            Attr::Ref(name) => format!("ref={{(el) => runWithOwner(owner, () => b.{name}(el))}}"),
        }
    }

    /// Nodes as the body of an element or expression, each on its own line.
    fn children(&mut self, nodes: &[Node], depth: usize) -> String {
        let saved = std::mem::take(&mut self.source);
        for node in nodes {
            self.node(node, depth);
        }
        std::mem::replace(&mut self.source, saved)
    }

    /// Nodes where one JSX expression is expected: a fragment unless there
    /// is exactly one element.
    fn expression(&mut self, nodes: &[Node], depth: usize) -> String {
        match nodes {
            [] => format!("{}null\n", pad(depth)),
            [Node::Element(_)] => self.children(nodes, depth),
            _ => {
                let inner = self.children(nodes, depth + 1);
                format!("{0}<>\n{inner}{0}</>\n", pad(depth))
            }
        }
    }

    fn node(&mut self, node: &Node, depth: usize) {
        let indent = pad(depth);
        match node {
            Node::Text(text) => {
                let _ = writeln!(self.source, "{indent}{}", jsx_text(text));
            }
            Node::Value(path) => {
                let (expr, ty) = self.path(path);
                assert!(
                    !(self.attaching && matches!(ty, Ty::Slot)),
                    "{}: `@if enhanced` can't hold a slot: an island's props leave slots out",
                    self.info.name
                );
                let _ = writeln!(self.source, "{indent}{{{expr}}}");
            }
            Node::Enhanced { body, fallback, .. } => {
                let body = self.expression(body, depth + 1);
                let fallback = self.expression(fallback, depth + 1);
                let _ = write!(
                    self.source,
                    "{indent}{{enhanced ? (\n{body}{indent}) : (\n{fallback}{indent})}}\n"
                );
            }
            Node::Element(element) => {
                // An attribute both the server and the behaviour set: the
                // server's until the behaviour runs, then the behaviour's.
                let mut attrs = Vec::new();
                for attr in &element.attrs {
                    let takeover = !attr.reads_behaviour()
                        && element
                            .attrs
                            .iter()
                            .any(|other| other.reads_behaviour() && other.name() == attr.name());
                    let taken = attr.reads_behaviour()
                        && element
                            .attrs
                            .iter()
                            .any(|other| !other.reads_behaviour() && other.name() == attr.name());
                    if taken {
                        continue;
                    }
                    if takeover {
                        let behaviours = element
                            .attrs
                            .iter()
                            .find(|other| other.reads_behaviour() && other.name() == attr.name())
                            .expect("checked");
                        let (name, server) = self.attr_value(attr).expect("an attribute");
                        let (_, enhanced) = self.attr_value(behaviours).expect("an attribute");
                        attrs.push(format!("{name}={{enhanced ? {enhanced} : {server}}}"));
                    } else {
                        attrs.push(self.attr(attr));
                    }
                }
                if let Some(path) = element.spread {
                    attrs.push(format!("{{...{}}}", path[0]));
                }
                let open = if attrs.is_empty() {
                    format!("<{}", element.tag)
                } else {
                    format!("<{} {}", element.tag, attrs.join(" "))
                };
                match &element.children {
                    None => {
                        let _ = writeln!(self.source, "{indent}{open} />");
                    }
                    Some(children) if children.is_empty() => {
                        let _ = writeln!(self.source, "{indent}{open}></{}>", element.tag);
                    }
                    Some(children) => {
                        let inner = self.children(children, depth + 1);
                        let _ = write!(
                            self.source,
                            "{indent}{open}>\n{inner}{indent}</{}>\n",
                            element.tag
                        );
                    }
                }
            }
            Node::If {
                cond,
                then,
                otherwise,
            } => {
                let cond = self.cond(cond);
                let then = self.expression(then, depth + 1);
                let otherwise = self.expression(otherwise, depth + 1);
                let _ = write!(
                    self.source,
                    "{indent}{{{cond} ? (\n{then}{indent}) : (\n{otherwise}{indent})}}\n"
                );
            }
            Node::IfLet {
                bind,
                path,
                then,
                otherwise,
            } => {
                let (expr, ty) = self.path(path);
                let inner = match ty {
                    Ty::Option(inner) => *inner,
                    other => other,
                };
                // A behaviour's value is a call TypeScript can't narrow.
                let bound = if expr.ends_with(')') {
                    format!("{expr}!")
                } else {
                    expr.clone()
                };
                self.scope.push((bind, bound, inner));
                let then = self.expression(then, depth + 1);
                self.scope.pop();
                let otherwise = self.expression(otherwise, depth + 1);
                let _ = write!(
                    self.source,
                    "{indent}{{{expr} != null ? (\n{then}{indent}) : (\n{otherwise}{indent})}}\n"
                );
            }
            Node::For { bind, path, body } => {
                self.uses_for = true;
                let (expr, ty) = self.path(path);
                let Ty::List(item) = ty else {
                    panic!("@for runs over a list")
                };
                self.scope.push((bind, (*bind).to_string(), *item));
                let body = self.expression(body, depth + 2);
                self.scope.pop();
                let _ = write!(
                    self.source,
                    "{indent}<For each={{{expr}}}>\n{indent}  {{({bind}) => (\n{body}{indent}  )}}\n{indent}</For>\n"
                );
            }
        }
    }
}

fn pad(depth: usize) -> String {
    "  ".repeat(depth)
}

fn string_attr(value: &str) -> String {
    if value.contains(['"', '&', '\\', '{', '}']) {
        format!("{{{value:?}}}")
    } else {
        format!("\"{value}\"")
    }
}

/// Text as JSX reads it back exactly: plain where it can be, else a string
/// expression (JSX trims whitespace at line ends and decodes entities).
fn jsx_text(text: &str) -> String {
    let plain =
        !text.is_empty() && text.trim() == text && !text.contains(['{', '}', '<', '>', '&', '\n']);
    if plain {
        text.to_string()
    } else {
        format!("{{{text:?}}}")
    }
}
